// X4 (phone link v2): console records on the pipe's console stream (slot 2)
// and the pairing code, generated by production code.
//
// Records: BLE_PhonePipeConsoleCore.h. P4 output is written the way the P4's
// writer does it (buildInfo, sliceLen/sliceFlags, Egress check/commit); the
// phone's verdict is hw1rec::PhoneReceiver (the agreed phone rules); the P4's
// verdict on phone records is hw1rec::scanIngress, record by record, as the
// console driver claims them. Message content (replies, help lines, file
// bytes) is synthetic. Codes: BLE_PhonePairCode.h (fromValues, display,
// parse) and the PSK from scPbkdf2 over the canonical code, as phonePipeStart
// derives it. Output is one JSON object per line; test_phone_secure_channel.py
// assembles phone_console_v2_records.json and compares it.
#include "BLE_PhonePipeConsoleCore.h"
#include "BLE_PhonePairCode.h"
#include "BLE_PhoneSecureChannel.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <map>
#include <string>
#include <vector>
#ifdef NDEBUG
#error "This generator requires assertions"
#endif
using Bytes=std::vector<uint8_t>;
using hw1rec::Verdict;
using hw1rec::Fault;

static std::string hex(const uint8_t* p,size_t n) {
  static const char digits[]="0123456789abcdef";std::string s;
  for(size_t i=0;i<n;++i){s+=digits[p[i]>>4];s+=digits[p[i]&15];}
  return s;
}
static std::string hex(const Bytes& b){return hex(b.data(),b.size());}
static Bytes text(const char* s){return Bytes(s,s+strlen(s));}
static Bytes cat(Bytes a,const Bytes& b){a.insert(a.end(),b.begin(),b.end());return a;}
static Bytes record(uint8_t type,uint8_t flags,const Bytes& payload) {
  Bytes r(hw1rec::kHeader+payload.size());
  assert(hw1rec::encode(r.data(),r.size(),type,flags,payload.data(),payload.size())==r.size());return r;
}
// A header claiming `len` with only `have` payload bytes after it.
static Bytes header(uint8_t type,uint8_t flags,uint16_t len,size_t have=0) {
  Bytes r(hw1rec::kHeader+have,0x2a);hw1rec::encodeHeader(r.data(),type,flags,len);return r;
}
// Printable synthetic text: lines of 64 bytes (63 letters and LF).
static Bytes lines(size_t n,char seed) {
  Bytes b(n);for(size_t i=0;i<n;++i)b[i]=uint8_t(i%64==63?'\n':'a'+(seed+i)%26);return b;
}
static Bytes pattern(size_t n,uint8_t seed){Bytes b(n);for(size_t i=0;i<n;++i)b[i]=uint8_t(seed+i*7);return b;}
// One OtaBleWire frame: 00 'HW1OTA' 01 | offset u32 BE | chunk.
static Bytes otaFrame(size_t size,uint32_t offset) {
  Bytes b=pattern(size,0x3c);std::memcpy(b.data(),hw1rec::kOtaMagic,sizeof(hw1rec::kOtaMagic));
  for(unsigned i=0;i<4;++i)b[8+i]=uint8_t(offset>>(8*(3-i)));
  return b;
}
static const char* kFirmware="0.0.0-fixture";  // synthetic INFO fields
static const char* kModel="HardwareOne";

// The P4's record output for one console stream, built as its writer builds it.
struct Writer {
  Bytes s;
  hw1rec::Egress e;
  void info(const char* fw,const char* model) {
    char out[hw1rec::kInfoMax+1];const size_t n=hw1rec::buildInfo(out,sizeof(out),fw,model);assert(n);
    s=cat(s,record(hw1rec::kInfo,0,Bytes(out,out+n)));
  }
  void push(uint8_t type,uint8_t flags,const uint8_t* p,size_t n) {
    assert(e.check(type,flags,n)==Fault::None);
    s=cat(s,record(type,flags,Bytes(p,p+n)));assert(e.commit(type,flags,n));
  }
  // One TEXT/BLOB chain (one sendBLEResponseToSession call); with cutAfter
  // records it ends with ABORT instead (the writer stalled).
  void chain(uint8_t type,const Bytes& data,size_t cutAfter=SIZE_MAX) {
    assert(hw1rec::chainFits(data.size()));
    size_t offset=0,records=0;
    while(offset<data.size()) {
      if(records==cutAfter){push(hw1rec::kAbort,0,nullptr,0);return;}
      const uint16_t n=hw1rec::sliceLen(data.size()-offset);
      push(type,hw1rec::sliceFlags(data.size()-offset),data.data()+offset,n);offset+=n;++records;
    }
    assert(!e.chainOpen());
  }
  // CARD (one record) or MIRROR (standalone records of at most 512 B).
  void single(uint8_t type,const Bytes& data) {
    const size_t cap=type==hw1rec::kCard?hw1rec::kCardMax:hw1rec::kMirrorMax;
    for(size_t offset=0;offset<data.size();){const size_t n=std::min(cap,data.size()-offset);
      push(type,0,data.data()+offset,n);offset+=n;}
  }
  // A command's output lines in whole-line batches of at most 512 B, one TEXT
  // chain per batch (bleCommandOutputLine's rule), then its result.
  void output(const std::vector<std::string>& lineList,const char* result) {
    std::string batch;
    for(const auto& line:lineList) {
      assert(line.size()<512);
      if(batch.size()+line.size()+1>512){chain(hw1rec::kText,Bytes(batch.begin(),batch.end()));batch.clear();}
      batch+=line;batch+='\n';
    }
    if(!batch.empty())chain(hw1rec::kText,Bytes(batch.begin(),batch.end()));
    chain(hw1rec::kText,text(result));
  }
};

struct Seen { size_t offset; hw1rec::Scan scan; Bytes payload; };
struct Result {
  std::vector<Seen> records;
  std::vector<std::pair<const char*,Bytes>> deliveries;
  const char* verdict="ok";Fault fault=Fault::None;long faultOffset=-1;
  unsigned skipped=0,ignored=0;
};
static Bytes payloadAt(const Bytes& s,size_t offset,const hw1rec::Scan& r) {
  const size_t from=std::min(s.size(),offset+hw1rec::kHeader);
  const size_t to=std::min(s.size(),offset+hw1rec::kHeader+r.header.len);
  return Bytes(s.begin()+long(from),s.begin()+long(to));
}
// The phone receiving the P4's stream.
static Result phoneSide(const Bytes& s) {
  Result out;hw1rec::PhoneReceiver rx;Bytes chain;
  for(size_t offset=0;offset<s.size();) {
    const hw1rec::Scan r=rx.next(s.data()+offset,s.size()-offset);
    out.records.push_back({offset,r,payloadAt(s,offset,r)});
    if(r.verdict==Verdict::Malformed){out.verdict="malformed";out.fault=r.fault;out.faultOffset=long(offset);break;}
    assert(r.verdict!=Verdict::NeedMore);
    const Bytes& p=out.records.back().payload;
    if(r.verdict==Verdict::Skip)++out.skipped;
    else if(r.verdict==Verdict::Ignore)++out.ignored;
    else switch(r.header.type) {
      case hw1rec::kInfo:out.deliveries.push_back({"info",p});break;
      case hw1rec::kText:case hw1rec::kBlob:
        chain=cat(chain,p);
        if(r.chainEnd){out.deliveries.push_back({r.header.type==hw1rec::kText?"text":"blob",chain});chain.clear();}
        break;
      case hw1rec::kCard:out.deliveries.push_back({"card",p});break;
      case hw1rec::kMirror:out.deliveries.push_back({"mirror",p});break;
      case hw1rec::kAbort:out.deliveries.push_back({"abort",chain});chain.clear();break;
      default:assert(false);
    }
    offset+=r.size;
  }
  return out;
}
// The P4 claiming the phone's records (driver ingress over scanIngress).
static Result p4Side(const Bytes& s) {
  Result out;
  for(size_t offset=0;offset<s.size();) {
    const hw1rec::Scan r=hw1rec::scanIngress(s.data()+offset,s.size()-offset);
    out.records.push_back({offset,r,payloadAt(s,offset,r)});
    if(r.verdict==Verdict::Malformed){out.verdict="malformed";out.fault=r.fault;out.faultOffset=long(offset);break;}
    assert(r.verdict==Verdict::Deliver || r.verdict==Verdict::Skip);
    if(r.verdict==Verdict::Skip)++out.skipped;
    else out.deliveries.push_back({r.header.type==hw1rec::kCommand?"command":"binary",out.records.back().payload});
    offset+=r.size;
  }
  return out;
}
static void emit(const char* id,const char* direction,const char* source,const char* description,const Bytes& s,
                 const Result& r) {
  const bool phone=!std::strcmp(direction,"p4_to_phone");
  printf("{\"type\":\"vector\",\"id\":\"%s\",\"direction\":\"%s\",\"source\":\"%s\",\"description\":\"%s\","
         "\"stream_hex\":\"%s\",\"records\":[",id,direction,source,description,hex(s).c_str());
  for(size_t i=0;i<r.records.size();++i) {
    const auto& x=r.records[i];
    printf("%s{\"offset\":%zu,\"type\":\"%s\",\"code\":%u,\"flags\":%u,\"len\":%u,\"payload_hex\":\"%s\","
           "\"verdict\":\"%s\",\"fault\":\"%s\"}",i?",":"",x.offset,hw1rec::typeName(x.scan.header.type),
           unsigned(x.scan.header.type),unsigned(x.scan.header.flags),unsigned(x.scan.header.len),
           hex(x.payload).c_str(),hw1rec::verdictName(x.scan.verdict),hw1rec::faultName(x.scan.fault));
  }
  printf("],\"deliveries\":[");
  for(size_t i=0;i<r.deliveries.size();++i)
    printf("%s{\"kind\":\"%s\",\"hex\":\"%s\"}",i?",":"",r.deliveries[i].first,hex(r.deliveries[i].second).c_str());
  const bool bad=!std::strcmp(r.verdict,"malformed");
  printf("],\"verdict\":\"%s\",\"fault\":\"%s\",\"fault_offset\":%ld,\"receiver_action\":\"%s\",\"skipped\":%u,"
         "\"ignored\":%u}\n",r.verdict,hw1rec::faultName(r.fault),r.faultOffset,
         bad?(phone?"stream_reset_1":"close_1"):"none",r.skipped,r.ignored);
}
// P4 output: written by the P4's path, so the phone must accept it.
static void p4Out(const char* id,const char* description,const Writer& w) {
  const Result r=phoneSide(w.s);assert(!std::strcmp(r.verdict,"ok"));
  emit(id,"p4_to_phone","p4_production",description,w.s,r);
}
// Bytes the P4 never writes: the phone's verdict under the agreed rules.
static void phoneRule(const char* id,const char* description,const Bytes& s,Fault expected,unsigned skipped=0,
                      unsigned ignored=0) {
  const Result r=phoneSide(s);assert(r.fault==expected && r.skipped==skipped && r.ignored==ignored);
  emit(id,"p4_to_phone","contract",description,s,r);
}
// Phone output: the P4's production verdict.
static void p4Rule(const char* id,const char* description,const Bytes& s,Fault expected,size_t deliveries,
                   unsigned skipped=0) {
  const Result r=p4Side(s);assert(r.fault==expected && r.deliveries.size()==deliveries && r.skipped==skipped);
  emit(id,"phone_to_p4","p4_production",description,s,r);
}

static std::vector<std::string> helpLines(unsigned count) {
  std::vector<std::string> out;
  for(unsigned i=0;i<count;++i) {
    char line[96];snprintf(line,sizeof(line),"  cmd%02u%*s synthetic help line %02u for the console fixture",
                           i,int(4+i%5),"",i);
    out.push_back(line);
  }
  return out;
}
static Bytes card() {
  return text("{\"kind\":\"system\",\"level\":\"info\",\"title\":\"Fixture\",\"msg\":\"synthetic card\",\"ms\":4000}");
}
static Bytes rawHeader(size_t size,size_t offset,size_t len,bool eof) {
  char h[192];snprintf(h,sizeof(h),"{\"success\":true,\"path\":\"/fixture.bin\",\"size\":%zu,\"offset\":%zu,"
                       "\"len\":%zu,\"eof\":%s,\"enc\":\"raw\"}",size,offset,len,eof?"true":"false");
  return text(h);
}
static Bytes infoRecord(){Writer w;w.info(kFirmware,kModel);return w.s;}
static Bytes withInfo(const Bytes& rest){return cat(infoRecord(),rest);}

static void records() {
  using namespace hw1rec;
  {Writer w;w.info(kFirmware,kModel);p4Out("info","INFO, the first record of every console stream",w);}
  {Writer w;w.info("0.0.0-\"q\"\\\t\x01\x7f\xc3\xa9",nullptr);
   p4Out("info_escaped","INFO with a quote, a backslash, TAB, 01 and DEL escaped, a non-ASCII byte as '?', no model",w);}
  {Writer w;std::string fw(80,'f'),model(63,'m');model+="\"tail";w.info(fw.c_str(),model.c_str());
   p4Out("info_long_fields","INFO strings cut at 64 escaped bytes, never inside an escape",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,text("OK: synthetic reply"));
   p4Out("text_one_record","a short result: one TEXT record",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,lines(4096,1));
   p4Out("text_4096","a 4096-byte result: three 1024-byte records with MORE, then 1024 without",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,lines(kChainMax,2));
   p4Out("text_4608_cap","a chain at the 4608-byte cap: four 1024-byte records with MORE, then 512",w);}
  {Writer w;w.info(kFirmware,kModel);w.output(helpLines(24),"OK");
   p4Out("help_output","a command's output lines as whole-line TEXT chains of at most 512 bytes, then its result OK",w);}
  {Writer w;w.info(kFirmware,kModel);w.output(helpLines(80),"OK");
   p4Out("help_all_output","a long output: many 512-byte-bounded TEXT chains, then OK",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kBlob,pattern(1300,0x42));w.chain(kText,rawHeader(5000,0,1300,false));
   p4Out("blob_then_raw_header","fileread bin: the BLOB chain (1024 with MORE, 276), then its enc:raw TEXT header",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kBlob,pattern(700,0x43));w.chain(kText,text("synthetic output line\n"));
   w.chain(kText,rawHeader(5000,4300,700,true));
   p4Out("blob_output_then_header","a BLOB chain, a batched output TEXT, then the enc:raw TEXT header",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kBlob,pattern(kChainMax,0x44));w.chain(kText,rawHeader(kChainMax,0,kChainMax,true));
   p4Out("blob_4608","a BLOB chain at the 4608-byte cap, then its header",w);}
  {Writer w;w.info(kFirmware,kModel);w.single(kCard,card());
   p4Out("card","CARD: the bare notification JSON object (no #NOTIF prefix, no newline)",w);}
  {Writer w;w.info(kFirmware,kModel);w.single(kMirror,lines(100,4));p4Out("mirror","MIRROR: one mirror buffer",w);}
  {Writer w;w.info(kFirmware,kModel);w.single(kMirror,lines(1100,5));
   p4Out("mirror_split","a 1100-byte mirror text as standalone MIRROR records of 512, 512 and 76 bytes",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,lines(1500,6),1);
   p4Out("abort_mid_chain","a 1500-byte TEXT chain cut by ABORT after its first record: output not confirmed",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,lines(3000,7),2);w.chain(kText,text("OK: next reply"));
   p4Out("abort_then_next","ABORT after two records; the stream carries on with the next reply",w);}
  {Writer w;w.info(kFirmware,kModel);w.chain(kText,lines(1500,8));w.single(kCard,card());w.single(kMirror,lines(40,9));
   w.chain(kText,text("OK"));
   p4Out("card_mirror_between_chains","CARD and MIRROR only between chains, never inside one",w);}

  // P4 -> phone, bytes the P4 never writes: the phone's rules.
  const Bytes more1024=record(kText,kMore,lines(1024,10));
  phoneRule("info_not_first","a TEXT before INFO",record(kText,0,text("OK")),Fault::InfoOrder);
  phoneRule("info_twice","a second INFO",withInfo(withInfo({})),Fault::InfoOrder);
  phoneRule("info_len_0","INFO with length 0",header(kInfo,0,0),Fault::Length);
  phoneRule("info_len_257","INFO with length 257",record(kInfo,0,lines(257,1)),Fault::Length);
  phoneRule("text_len_0","TEXT with length 0",withInfo(header(kText,0,0)),Fault::Length);
  phoneRule("text_len_1025","TEXT with length 1025",withInfo(record(kText,0,lines(1025,1))),Fault::Length);
  phoneRule("card_len_513","CARD with length 513",withInfo(record(kCard,0,lines(513,1))),Fault::Length);
  phoneRule("mirror_len_513","MIRROR with length 513",withInfo(record(kMirror,0,lines(513,1))),Fault::Length);
  phoneRule("info_more","INFO with MORE",record(kInfo,kMore,text("{}")),Fault::More);
  phoneRule("card_more","CARD with MORE",withInfo(record(kCard,kMore,card())),Fault::More);
  phoneRule("mirror_more","MIRROR with MORE",withInfo(record(kMirror,kMore,text("x"))),Fault::More);
  phoneRule("abort_more","ABORT with MORE",withInfo(cat(more1024,header(kAbort,kMore,0))),Fault::More);
  phoneRule("abort_len_1","ABORT with a 1-byte payload",withInfo(cat(more1024,record(kAbort,0,text("x")))),Fault::Length);
  phoneRule("flags_bit_1","TEXT with flag bit 1 (0x02)",withInfo(record(kText,0x02,text("OK"))),Fault::Flags);
  phoneRule("flags_bit_7","TEXT with flag bit 7 (0x80)",withInfo(record(kText,0x80,text("OK"))),Fault::Flags);
  phoneRule("unknown_more","an unknown type (0x40) with MORE: malformed, not skipped",
            withInfo(record(0x40,kMore,text("abc"))),Fault::More);
  phoneRule("ticket_more","TICKET (reserved) with MORE",withInfo(record(kTicket,kMore,pattern(18,1))),Fault::More);
  phoneRule("unknown_len_1025","an unknown type (0x40) with length 1025",withInfo(record(0x40,0,pattern(1025,1))),
            Fault::Length);
  phoneRule("unknown_skipped","an unknown type (0x40, 3 bytes) between INFO and TEXT: skipped and counted",
            withInfo(cat(record(0x40,0,text("abc")),record(kText,0,text("OK")))),Fault::None,1);
  phoneRule("unknown_len_0_skipped","an unknown type (0x7f) with length 0: skipped",
            withInfo(cat(header(0x7f,0,0),record(kText,0,text("OK")))),Fault::None,1);
  phoneRule("unknown_inside_chain_skipped","an unknown type inside an open TEXT chain: skipped, the chain goes on",
            withInfo(cat(cat(more1024,record(0x40,0,text("abc"))),record(kText,0,text("end")))),Fault::None,1);
  phoneRule("ticket_skipped","TICKET (reserved for P3, 18 bytes): skipped",
            withInfo(cat(record(kTicket,0,pattern(18,2)),record(kText,0,text("OK")))),Fault::None,1);
  phoneRule("ticket_inside_chain_skipped","TICKET inside an open TEXT chain: skipped",
            withInfo(cat(cat(more1024,record(kTicket,0,pattern(18,3))),record(kText,0,text("end")))),Fault::None,1);
  phoneRule("stray_abort_ignored","ABORT with no chain open: ignored",
            withInfo(cat(header(kAbort,0,0),record(kText,0,text("OK")))),Fault::None,0,1);
  phoneRule("interleave_card_in_chain","CARD inside an open TEXT chain",withInfo(cat(more1024,record(kCard,0,card()))),
            Fault::Interleave);
  phoneRule("interleave_mirror_in_chain","MIRROR inside an open TEXT chain",
            withInfo(cat(more1024,record(kMirror,0,text("m")))),Fault::Interleave);
  phoneRule("interleave_blob_in_text_chain","a BLOB record inside an open TEXT chain",
            withInfo(cat(more1024,record(kBlob,0,pattern(10,1)))),Fault::Interleave);
  phoneRule("interleave_text_in_blob_chain","a TEXT record inside an open BLOB chain",
            withInfo(cat(record(kBlob,kMore,pattern(1024,2)),record(kText,0,text("x")))),Fault::Interleave);
  phoneRule("interleave_info_in_chain","INFO inside an open TEXT chain",withInfo(cat(more1024,infoRecord())),
            Fault::InfoOrder);
  {Bytes s;for(unsigned i=0;i<4;++i)s=cat(s,record(kText,kMore,lines(1024,char(i))));
   phoneRule("chain_4609","a TEXT chain of 4609 bytes (4 x 1024 with MORE, then 513)",
             withInfo(cat(s,record(kText,0,lines(513,4)))),Fault::Cap);
   phoneRule("more_at_4608","MORE on the record that brings a chain to exactly 4608: no continuation could fit",
             withInfo(cat(s,record(kText,kMore,lines(512,4)))),Fault::Cap);}
  phoneRule("resume_at_phone","RESUME (phone -> P4, reserved) arriving at the phone",
            withInfo(record(kResume,0,pattern(16,1))),Fault::Direction);
  phoneRule("command_at_phone","COMMAND arriving at the phone",withInfo(record(kCommand,0,text("help"))),Fault::Direction);
  phoneRule("binary_at_phone","BINARY arriving at the phone",withInfo(record(kBinary,0,otaFrame(13,0))),Fault::Direction);

  // Phone -> P4: the P4's production ingress verdict.
  p4Rule("command","COMMAND help",record(kCommand,0,text("help")),Fault::None,1);
  {std::string line="echo ";line+=std::string(kCommandMax-line.size(),'x');
   p4Rule("command_511","a 511-byte COMMAND (the line limit)",record(kCommand,0,text(line.c_str())),Fault::None,1);
   line+='x';p4Rule("command_512","a 512-byte COMMAND",record(kCommand,0,text(line.c_str())),Fault::Length,0);}
  p4Rule("command_len_0","COMMAND with length 0",header(kCommand,0,0),Fault::Length,0);
  p4Rule("command_more","COMMAND with MORE",record(kCommand,kMore,text("help")),Fault::More,0);
  p4Rule("command_flags_bit_1","COMMAND with flag bit 1 (0x02)",record(kCommand,0x02,text("help")),Fault::Flags,0);
  p4Rule("command_raw_bytes","COMMAND bytes are delivered unchanged (TAB, CR and NUL included)",
         record(kCommand,0,Bytes{'l','s','\t','/','\r',0}),Fault::None,1);
  p4Rule("records_back_to_back","COMMAND, COMMAND and BINARY in one write",
         cat(cat(record(kCommand,0,text("status")),record(kCommand,0,text("uptime"))),record(kBinary,0,otaFrame(13,0))),
         Fault::None,3);
  p4Rule("binary_13","the smallest BINARY: the 12-byte OtaBleWire head and one byte",
         record(kBinary,0,otaFrame(kBinaryMin,0)),Fault::None,1);
  p4Rule("binary_489","the largest BINARY: 12-byte head and 477 bytes",
         record(kBinary,0,otaFrame(kBinaryMax,4096)),Fault::None,1);
  p4Rule("binary_12","a 12-byte BINARY (no chunk)",record(kBinary,0,otaFrame(12,0)),Fault::Length,0);
  p4Rule("binary_490","a 490-byte BINARY",record(kBinary,0,otaFrame(490,0)),Fault::Length,0);
  {Bytes f=otaFrame(64,0);f[1]='X';
   p4Rule("binary_bad_magic","BINARY without the 00 'HW1OTA' 01 prefix",record(kBinary,0,f),Fault::Magic,0);}
  p4Rule("binary_more","BINARY with MORE",record(kBinary,kMore,otaFrame(64,0)),Fault::More,0);
  p4Rule("resume_skipped","RESUME (reserved for P3, 16 bytes) then COMMAND: RESUME skipped and counted",
         cat(record(kResume,0,pattern(16,4)),record(kCommand,0,text("help"))),Fault::None,1,1);
  p4Rule("unknown_skipped_at_p4","an unknown type (0x90, 5 bytes) then COMMAND: skipped and counted",
         cat(record(0x90,0,pattern(5,5)),record(kCommand,0,text("help"))),Fault::None,1,1);
  p4Rule("unknown_more_at_p4","an unknown type (0x90) with MORE",record(0x90,kMore,pattern(5,5)),Fault::More,0);
  p4Rule("unknown_len_1025_at_p4","an unknown type (0x90) with length 1025",record(0x90,0,pattern(1025,5)),Fault::Length,0);
  p4Rule("ticket_at_p4","TICKET (P4 -> phone, reserved) arriving at the P4",record(kTicket,0,pattern(18,6)),
         Fault::Direction,0);
  p4Rule("text_at_p4","TEXT arriving at the P4",record(kText,0,text("OK")),Fault::Direction,0);
  p4Rule("info_at_p4","INFO arriving at the P4",record(kInfo,0,text("{}")),Fault::Direction,0);
  p4Rule("abort_at_p4","ABORT arriving at the P4",header(kAbort,0,0),Fault::Direction,0);
}

// ---- Pairing code -----------------------------------------------------------
static std::map<std::string,std::string> psks;
static std::string pskOf(const std::string& canonical) {
  auto it=psks.find(canonical);if(it!=psks.end())return it->second;
  uint8_t key[32];
  assert(hw1sc::scPbkdf2(reinterpret_cast<const uint8_t*>(canonical.data()),canonical.size(),
    reinterpret_cast<const uint8_t*>(hw1phone::kPipeLabel),strlen(hw1phone::kPipeLabel),100000,key));
  return psks[canonical]=hex(key,32);
}
// Why a text is not a code, by the parse steps (cross-checked with parse()).
static const char* reasonOf(const std::string& in) {
  size_t a=0,b=in.size();
  while(a<b && hw1code::outerSpace(uint8_t(in[a])))++a;
  while(b>a && hw1code::outerSpace(uint8_t(in[b-1])))--b;
  uint8_t v[17]{};size_t n=0;
  for(size_t i=a;i<b;++i) {
    if(in[i]=='-' || in[i]==' ')continue;
    const int value=hw1code::valueOf(uint8_t(in[i]));if(value<0)return "symbol";
    if(n<17)v[n]=uint8_t(value);++n;
  }
  if(n!=hw1code::kSymbols)return "length";
  return hw1code::checkValue(v)==v[15]?"":"check";
}
static void code(const std::string& id,const std::string& input) {
  char canonical[17];const bool ok=hw1code::parse(input.data(),input.size(),canonical);
  const char* reason=reasonOf(input);assert(ok==!*reason);
  char shown[20]="";if(ok)hw1code::display(canonical,shown);
  printf("{\"type\":\"code\",\"id\":\"%s\",\"input_hex\":\"%s\",\"accepted\":%s,",id.c_str(),
         hex(reinterpret_cast<const uint8_t*>(input.data()),input.size()).c_str(),ok?"true":"false");
  if(ok)printf("\"canonical\":\"%s\",\"display\":\"%s\",\"normalised_hex\":\"%s\",\"psk_hex\":\"%s\",",canonical,shown,
               hex(reinterpret_cast<const uint8_t*>(canonical),16).c_str(),pskOf(canonical).c_str());
  else printf("\"canonical\":null,\"display\":null,\"normalised_hex\":null,\"psk_hex\":null,");
  printf("\"reason\":\"%s\"}\n",reason);
}
static std::string fromValues(const uint8_t v[15]){char c[17];hw1code::fromValues(v,c);return c;}
static std::string displayOf(const std::string& c){char d[20];hw1code::display(c.c_str(),d);return d;}
static std::string lower(std::string s){for(auto& c:s)if(c>='A'&&c<='Z')c=char(c-'A'+'a');return s;}

static void codes() {
  uint8_t zeros[15]{},ones[15],seq[15],tail[15];
  for(unsigned i=0;i<15;++i){ones[i]=31;seq[i]=uint8_t(i);tail[i]=uint8_t(17+i);}
  const std::string k=fromValues(seq);
  code("canonical_zeros",fromValues(zeros));
  code("canonical_all_31",fromValues(ones));
  code("canonical_sequence",k);
  code("canonical_tail",fromValues(tail));
  {const uint32_t words[3]={0x01234567u,0x89abcdefu,0x0f1e2d3cu};char c[17];hw1code::fromRandom(words,c);
   code("canonical_from_random_words",c);}
  // Entry normalisation over the canonical_sequence code.
  const std::string shown=displayOf(k);
  code("display_form",shown);
  code("lowercase",lower(k));
  code("lowercase_display",lower(shown));
  {std::string s=shown;for(auto& c:s)if(c=='-')c=' ';code("spaces_for_dashes",s);}
  code("extra_separators","--"+k.substr(0,4)+" - "+k.substr(4,4)+"--"+k.substr(8,4)+"  "+k.substr(12)+"-");
  code("outer_whitespace","\t \n"+shown+"\r\n\v\f ");
  {std::string s=k;assert(s[0]=='0' && s[1]=='1');s[0]='O';s[1]='I';code("o_and_i_aliases",s);
   s[0]='o';s[1]='l';code("lowercase_o_and_l_aliases",s);s[1]='L';code("uppercase_l_alias",s);}
  // Not a code (stays a passphrase on both sides).
  {std::string s=k;s[5]='U';code("contains_u",s);}
  code("fifteen_symbols",k.substr(0,15));
  code("seventeen_symbols",k+"0");
  code("inner_tab",k.substr(0,8)+"\t"+k.substr(8));
  code("inner_newline",k.substr(0,8)+"\n"+k.substr(8));
  code("non_ascii",k.substr(0,15)+"\xc3\x89");
  code("trailing_punctuation",k+"!");
  code("empty","");
  code("only_separators","---- ----");
  code("passphrase","SyntheticPipe!123");
  // Every single wrong symbol and every swap of two different neighbours.
  for(size_t i=0;i<16;++i)for(unsigned v=0;v<32;++v) {
    if(hw1code::kAlphabet[v]==k[i])continue;
    std::string s=k;s[i]=hw1code::kAlphabet[v];
    char id[48];snprintf(id,sizeof(id),"single_error_%02zu_%c",i,hw1code::kAlphabet[v]);code(id,s);
  }
  for(size_t i=0;i+1<16;++i) {
    if(k[i]==k[i+1])continue;
    std::string s=k;std::swap(s[i],s[i+1]);char id[32];snprintf(id,sizeof(id),"swap_%02zu_%02zu",i,i+1);code(id,s);
  }
}

static void meta() {
  using namespace hw1rec;
  printf("{\"type\":\"meta\",\"types\":{\"INFO\":%u,\"TEXT\":%u,\"BLOB\":%u,\"CARD\":%u,\"MIRROR\":%u,\"ABORT\":%u,"
         "\"TICKET\":%u,\"COMMAND\":%u,\"BINARY\":%u,\"RESUME\":%u},\"limits\":{\"payload\":%zu,\"chain\":%zu,"
         "\"info\":%zu,\"text\":%zu,\"card\":%zu,\"mirror\":%zu,\"command\":%zu,\"binary_min\":%zu,\"binary_max\":%zu,"
         "\"unknown\":%zu,\"info_field\":%zu},\"binary_prefix_hex\":\"%s\",\"code_alphabet\":\"%s\",\"code_symbols\":%zu,"
         "\"code_modulus\":%u}\n",
         kInfo,kText,kBlob,kCard,kMirror,kAbort,kTicket,kCommand,kBinary,kResume,kPayloadMax,kChainMax,kInfoMax,
         kTextMax,kCardMax,kMirrorMax,kCommandMax,kBinaryMin,kBinaryMax,kUnknownMax,kInfoField,
         hex(kOtaMagic,sizeof(kOtaMagic)).c_str(),hw1code::kAlphabet,hw1code::kSymbols,unsigned(hw1code::kModulus));
}

int main() {
  assert(sodium_init()>=0);
  meta();records();codes();
  return 0;
}
